sql_query:
SELECT v.VAR_id
FROM varInfo v
WHERE v.gene_name = 'NEK1' AND v.HighImpact AND v.CADDphred > 20;

SELECT varInfo.VAR_id, CHROM, POS, ID, REF, ALT, QUAL, FILTER, AC, AN, AF, gene_name, HighImpact, ModerateImpact, Synonymous, CADDphred, PolyPhen, SIFT
FROM varInfo
WHERE gene_name = 'NEK1' AND HighImpact = 1 AND CADDphred > 20;

SELECT vi.VAR_id 
FROM varInfo vi 
WHERE vi.gene_name = 'NEK1' AND vi.HighImpact = 1 AND vi.CADDphred > 20;

SELECT v.VAR_id
FROM varInfo v
WHERE v.gene_name = 'NEK1' AND v.HighImpact = 1 AND v.CADDphred > 20;

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT = 'deleterious';

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT = 'deleterious';

SELECT COUNT(*) 
FROM varInfo 
WHERE gene_name = 'TARDBP' AND SIFT LIKE '%deleterious%';

SELECT AVG(AF) AS avg_AF
FROM varInfo
WHERE Synonymous = 1 OR ModerateImpact = 1 OR HighImpact = 1;

SELECT AVG(AF) AS avg_AF
FROM varInfo
WHERE Synonymous = 1 OR ModerateImpact = 1 OR HighImpact = 1;

SELECT AVG(AF) AS avg_AF 
FROM varInfo 
WHERE Synonymous = 1 OR ModerateImpact = 1 OR HighImpact = 1;

SELECT AVG(age) 
FROM pheno 
WHERE pheno = 'ALS';

SELECT AVG(age) 
FROM pheno 
WHERE pheno = 'ALS';

SELECT varInfo.VAR_id, varInfo.CHROM, varInfo.POS, varInfo.ID, varInfo.REF, varInfo.ALT, varInfo.QUAL, varInfo.FILTER, varInfo.AC, varInfo.AN, varInfo.AF, varInfo.gene_name, varInfo.HighImpact, varInfo.ModerateImpact, varInfo.Synonymous, varInfo.CADDphred, varInfo.PolyPhen, varInfo.SIFT
FROM varInfo
ORDER BY varInfo.CADDphred DESC, varInfo.AF DESC;

SELECT DISTINCT VAR_id 
FROM varInfo 
WHERE Synonymous = 1 AND HighImpact = 1;

SELECT DISTINCT v.VAR_id 
FROM varInfo v 
WHERE v.Synonymous = 1 AND v.HighImpact = 1;

SELECT AVG(AF) AS MAF
FROM varInfo
WHERE gene_name = 'TARDBP' AND ModerateImpact = 1;

SELECT AVG(AF) AS MAF
FROM varInfo
WHERE gene_name = 'TARDBP' AND ModerateImpact = 1;

SELECT AVG(AF) AS MAF
FROM varInfo
WHERE gene_name = 'TARDBP' AND ModerateImpact = 1;

SELECT AVG(AF) AS MAF
FROM varInfo
WHERE gene_name = 'TARDBP' AND ModerateImpact = 1;
